lean_type:
True ↔
  ∀ {X : Type} [Nonempty X] [Fintype X] (F : Set (Set X)),
    IsLowerSet F → ∃ x, ∀ F' ⊆ F, F'.Intersecting → Cardinal.mk ↑F' ≤ Cardinal.mk ↑{A | A ∈ F ∧ x ∈ A}

∀ n ≥ 1,
  have P := ∏ i ∈ Finset.range (n + 1), Nat.nth Nat.Prime i;
  ∃ p, Nat.Prime p ∧ Nat.Prime (P + p) ∧ Nat.nth Nat.Prime n < p ∧ p < P

True ↔
  ∀ {G : Type u_1} [inst : AddCommGroup G] [inst_1 : Fintype G] [inst_2 : DecidableEq G] (A : Finset G),
    have N := Fintype.card G;
    have α := ↑A.card / ↑N;
    have valid_tuples := {t | ∀ (i j : Fin 5), j ∈ {i, i + 1, i + 2} → t.1 i + t.2 j ∈ A};
    ↑valid_tuples.card ≥ α ^ 15 * ↑N ^ 10
